INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 18, 'theory', 'Quiz: the engine and its database');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 0, 'What is the engine-setup answer file for?', '["To store portal users'' passwords", "To back up virtual machines", "To repeat the installation without questions using the same answers", "To change a cluster''s compatibility version"]', 2, 'The answer file keeps the answers to the installation questions; passing it to engine-setup runs the installation without questions. This gives identical engines.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 1, 'What does compensation do when an engine command fails?', '["It rolls back the database changes from saved snapshots", "It restarts the host where the failure happened", "It deletes the related events from audit_log", "It repeats the command until it succeeds"]', 0, 'Compensation returns the database to its state before the command from saved snapshots. The events stay: they show what happened.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 2, 'A user was granted the ClusterAdmin role on a cluster. What can they manage?', '["Only the cluster itself as a database record", "The whole data center", "Only machines they created themselves", "The cluster and the hosts and machines nested in it"]', 3, 'A permission applies to the object and to everything nested in it. It does not spread up to the data center or sideways to neighboring clusters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 3, 'What does NOT end up in an engine-backup archive?', '["The dump of the engine database", "Virtual machine disks on the storage", "The engine configuration files", "The certificate authority files"]', 1, 'The archive holds the state of the engine itself: the database, settings, PKI. Machine disks lie on the storage and are copied separately.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 18, 4, 'When does a value written by engine-config take effect?', '["Immediately, without a restart", "After the hosts are restarted", "After the ovirt-engine service is restarted", "After the virtual machines are reinstalled"]', 2, 'Global keys are read when the engine starts, so it is restarted after a write. Cluster settings made in the portal apply at once.');
